      long[] r = new long[N + 1], b = new long[N + 1];
      r[N] = 1;
      for (int i = N - 1;i > 0;-- i) {
        r[i] = (1 + X) * r[i + 1] + b[i + 1];
        b[i] = X * Y * r[i + 1] + Y * b[i + 1];
      }
      out.println(b[1]);
    }
  }
}

